<script setup lang="ts">
import {computed,nextTick,ref,watch,onBeforeUnmount} from 'vue';
import {useLab} from '../store';
import type {Wire} from '../api';
import type {QueryComparison} from '../generated/QueryComparison';
import SqlEditor from './SqlEditor.vue';
import ResultTable from './ResultTable.vue';
import TraceView from './TraceView.vue';
import {comparisonExamples} from '../comparisonExamples';
defineProps<{theme:string}>();const lab=useLab();
function saved(key:string){const v=lab.workspace?.view;return v&&typeof v==='object'&&!Array.isArray(v)&&typeof v[key]==='string'?String(v[key]):undefined;}
const initial=comparisonExamples(lab.schema);const left=ref(saved('compare_left')??initial[0]);const right=ref(saved('compare_right')??initial[1]);const edited=ref(!!saved('compare_left'));const result=ref<Wire<QueryComparison>>();const active=ref(0);const leftEditor=ref<InstanceType<typeof SqlEditor>>();const rightEditor=ref<InstanceType<typeof SqlEditor>>();
const step=computed(()=>result.value?.steps[active.value]);const leftStep=computed(()=>step.value?.left==null?undefined:result.value?.left.steps.find(s=>s.id===step.value?.left));const rightStep=computed(()=>step.value?.right==null?undefined:result.value?.right.steps.find(s=>s.id===step.value?.right));
watch([left,right,()=>lab.engine],()=>{lab.invalidateJobs(['compare']);result.value=undefined});watch(()=>lab.epoch,()=>{result.value=undefined});
watch(()=>JSON.stringify(lab.schema.relations.map(r=>[r.name,r.columns.map(c=>c.name)])),()=>{if(!edited.value)[left.value,right.value]=comparisonExamples(lab.schema);else result.value=undefined;});
function persist(){edited.value=true;const v=lab.workspace?.view;if(v&&typeof v==='object'&&!Array.isArray(v)){v.compare_left=left.value;v.compare_right=right.value;lab.markDirty();}}
function update(side:'left'|'right',value:string){if(side==='left'){if(left.value===value)return;left.value=value;}else{if(right.value===value)return;right.value=value;}persist();}
function examples(){[left.value,right.value]=comparisonExamples(lab.schema);persist();}
async function select(index:number){active.value=index;await nextTick();leftEditor.value?.highlight(step.value?.left_range??null);rightEditor.value?.highlight(step.value?.right_range??null);}
async function compare(){const a=left.value,b=right.value;await Promise.all([leftEditor.value?.source(true),rightEditor.value?.source(true)]);if(a!==left.value||b!==right.value)return;const r=await lab.run<Wire<QueryComparison>>('compare','compare_queries',{engine:'sqlite',left:a,right:b});if(r){result.value=r;await select(r.first_difference??0);}}
onBeforeUnmount(()=>lab.invalidateJobs(['compare']));
</script>
<template><section class="query-comparison"><h2>两条 SQL，同一份冻结数据</h2><p>按行多重集比较，列按位置对应。相同结果只代表当前快照；高亮的条件变化与结果差异不自动构成因果证明。</p><div class="compare-inputs"><section><label for="query-a">查询 A</label><div class="compare-editor" id="query-a"><SqlEditor ref="leftEditor" id="compare-left" :model-value="left" :schema="lab.schema" :theme="theme" @update:model-value="update('left',$event)" @run="compare"/></div></section><section><label for="query-b">查询 B</label><div class="compare-editor" id="query-b"><SqlEditor ref="rightEditor" id="compare-right" :model-value="right" :schema="lab.schema" :theme="theme" @update:model-value="update('right',$event)" @run="compare"/></div></section></div><div class="toolbar"><button class="primary" :disabled="lab.engine!=='sqlite'||!!lab.jobs.compare||!left.trim()||!right.trim()" @click="compare">生成同快照对照</button><button @click="examples">使用当前数据库示例</button></div><p v-if="!lab.schema.relations.length" class="notice">当前数据库没有表。创建表后生成示例，或自行输入只读查询。</p><p v-if="lab.engine!=='sqlite'" class="notice">对照使用 SQLite；MySQL 仍使用单查询过程及真实会话实验。</p><template v-if="result"><p class="notice">{{result.diff.equal?'当前结果多重集相同':'当前结果存在差异'}} · A {{result.left.result.rows.length}} 行 / B {{result.right.result.rows.length}} 行</p><div class="compare-outputs"><ResultTable :table="result.left.result" :diff-rows="result.diff.expected" title="查询 A 最终结果"/><ResultTable :table="result.right.result" :diff-rows="result.diff.actual" title="查询 B 最终结果"/></div><h3>关键操作对照</h3><p v-if="result.first_difference!=null">首个可比差异：{{result.steps[result.first_difference]?.kind}}。点击步骤查看中间表和相应 SQL 范围。</p><div class="comparison-steps"><button v-for="(s,i) in result.steps" :key="s.key" :class="{active:i===active,different:s.diff&&!s.diff.equal}" @click="select(i)">{{s.kind}} · {{s.diff?(s.diff.equal?'结果相同':'结果不同'):'单独展示'}}{{s.changed_condition?' · 条件变化':''}}</button></div><section v-if="step" class="comparison-step-detail"><p>{{step.message}}</p><div class="compare-outputs"><ResultTable v-if="leftStep" :table="leftStep.table" :diff-rows="step.diff?.expected" :title="`A · ${leftStep.title}`" compact/><ResultTable v-if="rightStep" :table="rightStep.table" :diff-rows="step.diff?.actual" :title="`B · ${rightStep.title}`" compact/></div></section><details class="global-flow"><summary>展开两条完整查询过程</summary><TraceView :trace="result.left" @highlight="leftEditor?.highlight($event)"/><TraceView :trace="result.right" @highlight="rightEditor?.highlight($event)"/></details></template></section></template>
